const cfg = $('Code - prepare monitor window').first().json;
const rows = $input.all().map((i) => i.json).filter((r) => r.message_id);

const seen = new Set();
const unique = [];
for (const row of rows) {
  if (seen.has(row.message_id)) continue;
  seen.add(row.message_id);
  unique.push({ ...row, received_at: row.message_at ?? row.received_at });
}

unique.sort((a, b) => new Date(b.received_at) - new Date(a.received_at));

return [{
  json: {
    ...cfg,
    messages: unique,
    message_count: unique.length,
    has_messages: unique.length > 0,
  },
}];

const data = $('Code - combine message sources').first().json;
return [{
  json: {
    ...data,
    relevance_score: null,
    score_threshold: 20,
    passes_threshold: false,
    score_reason: 'No relevant info found in monitoring window',
    message_corpus: '',
    log_outcome: 'no_messages',
    model_name: 'google/gemini-2.5-flash-preview',
  },
}];

const allSlots = [];

for (const item of $input.all()) {
  const config = item.json;
  if (!config?.id || !config.from_date) continue;

  const refreshSeconds = parseInt(config.refresh_seconds, 10) || 3600;
  const fromDate = new Date(config.from_date);
  if (Number.isNaN(fromDate.getTime())) continue;

  const now = new Date();
  if (now < fromDate) continue;

  const gmt8Offset = 8 * 60 * 60 * 1000;
  const elapsedMs = now.getTime() - fromDate.getTime();
  const intervalMs = refreshSeconds * 1000;
  const completedIntervals = Math.floor(elapsedMs / intervalMs);
  let nextSlotTimeMs = fromDate.getTime() + ((completedIntervals + 1) * intervalMs);

  for (let i = 0; i < 100; i++) {
    const slotDate = new Date(nextSlotTimeMs + (i * intervalMs));
    allSlots.push({
      json: {
        slot_index: i + 1,
        timestamp_utc: slotDate.toISOString(),
        timestamp_gmt8: new Date(slotDate.getTime() + gmt8Offset).toISOString().replace('Z', '+08:00'),
        ...config,
        keywords: config.what_content_keywords ?? [],
        content_types: config.what_content_types ?? [],
        group_ids: config.from_group_ids ?? [],
        contact_jids: config.from_contact_jids ?? [],
        recipients: config.to_receipient_phone_ids ?? [],
        score_threshold: 20,
        model_name: 'google/gemini-2.5-flash-preview',
      },
    });
  }
}

if (!allSlots.length) {
  return [{ json: { skipped: true, reason: 'No eligible monitor_settings with connected WhatsApp pairing' } }];
}

return allSlots;

const EXECUTE_WINDOW_MS = 15 * 60 * 1000;
const nowMs = Date.now();
for (const item of $input.all()) {
  const slotUtcStr = item.json.timestamp_utc;
  if (!slotUtcStr) continue;
  const slotMs = new Date(slotUtcStr).getTime();
  const timeDifference = slotMs - nowMs;
  if (timeDifference >= 0 && timeDifference <= EXECUTE_WINDOW_MS) {
    return [{
      json: {
        ...item.json,
        match_found: true,
        matched_slot_utc: slotUtcStr,
        matched_slot_gmt8: item.json.timestamp_gmt8,
        minutes_until_slot: (timeDifference / 60000).toFixed(2),
      },
    }];
  }
}
return [{ json: { match_found: false } }];

const row = $input.first().json;
const refreshSeconds = parseInt(row.refresh_seconds, 10) || 3600;
const slotEnd = new Date(row.matched_slot_utc ?? row.timestamp_utc);
const slotStart = new Date(slotEnd.getTime() - refreshSeconds * 1000);

const keywords = row.what_content_keywords ?? row.keywords ?? [];
const contentTypes = row.what_content_types ?? row.content_types ?? [];
const groupIds = row.from_group_ids ?? row.group_ids ?? [];
const contactJids = row.from_contact_jids ?? row.contact_jids ?? [];
const recipients = row.to_receipient_phone_ids ?? row.recipients ?? [];

return [{
  json: {
    ...row,
    window_start: slotStart.toISOString(),
    window_end: slotEnd.toISOString(),
    matched_slot_at: slotEnd.toISOString(),
    group_ids: groupIds,
    contact_jids: contactJids,
    keywords,
    content_types: contentTypes,
    recipients,
    api_key: row.api_key ?? null,
    connection_phone: row.connection_phone ?? row.owner_phone_num ?? null,
    score_threshold: row.score_threshold ?? 20,
    model_name: row.model_name ?? 'google/gemini-2.5-flash-preview',
  },
}];

const data = $input.first().json;
const cfg = data;
const rows = data.messages ?? [];

function formatGmt8(value) {
  if (!value) return 'unknown time';
  const d = new Date(value);
  if (Number.isNaN(d.getTime())) return String(value);
  return d.toLocaleString('en-MY', {
    timeZone: 'Asia/Kuala_Lumpur',
    weekday: 'short',
    day: 'numeric',
    month: 'short',
    hour: 'numeric',
    minute: '2-digit',
    hour12: true,
  }) + ' (GMT+8)';
}

const allowedTypes = (cfg.content_types ?? []).map((t) => String(t).toLowerCase());
const typeMap = {
  text: ['text'],
  audio: ['audio'],
  images: ['image', 'sticker'],
  image: ['image', 'sticker'],
  documents: ['document'],
  document: ['document'],
  video: ['video'],
};
const allowed = new Set();
for (const t of allowedTypes) {
  for (const x of (typeMap[t] ?? [t])) allowed.add(x);
}
const filtered = allowed.size
  ? rows.filter((r) => allowed.has(String(r.content_type ?? '').toLowerCase()))
  : rows;

const lines = filtered.map((r) => {
  const body = [r.message_body, r.media_text].filter(Boolean).join(' | ');
  const tag = r.source_kind === 'media_interpretation' ? 'media' : 'text';
  const when = formatGmt8(r.received_at ?? r.message_at);
  const who = r.sender_phone ?? r.chat_jid ?? 'unknown sender';
  return `• ${when} | ${who} | (${r.content_type}/${tag}) ${body || '(empty)'}`;
});

let message_corpus = lines.join('\n') || '(no messages in this window)';
if (message_corpus.length > 12000) {
  message_corpus = message_corpus.slice(0, 12000) + '\n...(truncated)';
}

const kw = (cfg.keywords ?? []).join(', ') || 'none specified';
const types = (cfg.content_types ?? []).join(', ') || 'all';
const groups = (cfg.group_ids ?? []).join(', ') || 'none';
const contacts = (cfg.contact_jids ?? []).join(', ') || 'none';
const recipients = (cfg.recipients ?? []).join(', ') || 'none';
const owner = cfg.owner_email ?? 'unknown';
const phone = cfg.connection_phone ?? cfg.owner_phone_num ?? 'unknown';
const monitorName = cfg.monitor_name ?? 'Untitled';
const windowLabel = `${formatGmt8(cfg.window_start)} → ${formatGmt8(cfg.window_end)}`;

const WA_RULES = [
  'WHATSAPP OUTPUT RULES (strict):',
  '- Write for WhatsApp plain text only — NOT markdown.',
  '- Use *single asterisks* for bold titles and labels. Never use ## headers or **double asterisks**.',
  '- Every timestamp must be friendly GMT+8, e.g. "Sun, 8 Jun 8:52 AM (GMT+8)". Never use ISO like 2026-06-08T00:52:28.000Z.',
  '- Keep lines short. Use • for bullets. One alert per bullet.',
  '- Do NOT repeat the monitor title or window — those are added in the message header.',
  '- Skip empty sections entirely.',
].join('\n');

const score_prompt = [
  'You score WhatsApp monitor relevance for ActionNow.',
  '',
  `Owner: ${owner} (paired WhatsApp: ${phone})`,
  `Monitor name: ${monitorName}`,
  `Watch keywords: ${kw}`,
  `Allowed content types: ${types}`,
  `Monitored group JIDs: ${groups}`,
  `Monitored contact JIDs: ${contacts}`,
  `Window (GMT+8): ${windowLabel}`,
  `Message count: ${filtered.length}`,
  '',
  'Messages:',
  message_corpus,
  '',
  'Return ONLY valid JSON (no markdown):',
  '{"relevance_score": <integer 0-100>, "brief_reason": "<one sentence>"}',
  '',
  'Scoring: 100 = nearly all messages relate to keywords/topic; 0 = none relate.',
].join('\n');

const report_prompt = [
  'You write ActionNow WhatsApp monitoring alerts.',
  '',
  WA_RULES,
  '',
  `Monitor: ${monitorName}`,
  `Keywords: ${kw}`,
  `Content types: ${types}`,
  `Window (GMT+8): ${windowLabel}`,
  '',
  'Source messages:',
  message_corpus,
  '',
  'Output EXACTLY this structure (omit a section if nothing to show):',
  '',
  '*📌 SUMMARY*',
  '<2-3 short sentences, plain language>',
  '',
  '*🚨 ALERTS*',
  '• *<short alert label>* — "<key quote>" — *From:* +60… — *When:* Sun, 8 Jun 8:52 AM (GMT+8)',
  '',
  '*💬 MESSAGES*',
  '• *From:* +60… — *When:* Sun, 8 Jun 8:42 AM (GMT+8) — (<type>) "<quote or summary>"',
  '',
  'Be specific. Only include messages matching keywords or the monitor topic.',
].join('\n');

return [{
  json: {
    ...cfg,
    messages: filtered,
    message_count: filtered.length,
    message_corpus,
    score_prompt,
    report_prompt,
    window_label_gmt8: windowLabel,
    model_name: cfg.model_name ?? 'google/gemini-2.5-flash-preview',
  },
}];

const prep = $('Code - build message corpus').first().json;
const raw = $input.first().json.text ?? $input.first().json.response ?? '';
let relevance_score = 0;
let brief_reason = '';
try {
  const m = String(raw).match(/\{[\s\S]*\}/);
  const parsed = m ? JSON.parse(m[0]) : {};
  relevance_score = Number(parsed.relevance_score ?? 0);
  brief_reason = String(parsed.brief_reason ?? '').trim();
} catch (e) {
  brief_reason = 'Failed to parse LLM score JSON';
}
if (Number.isNaN(relevance_score)) relevance_score = 0;
relevance_score = Math.max(0, Math.min(100, Math.round(relevance_score)));
const SCORE_THRESHOLD = prep.score_threshold ?? 20;
const passes_threshold = relevance_score > SCORE_THRESHOLD;
return [{
  json: {
    ...prep,
    relevance_score,
    score_reason: brief_reason,
    score_threshold: SCORE_THRESHOLD,
    passes_threshold,
    log_outcome: passes_threshold ? 'passed_score' : 'not_send',
    report_prompt: [
      prep.report_prompt ?? '',
      '',
      `Relevance score: ${relevance_score}/100 (${brief_reason})`,
      `Only include content that passed the score threshold (> ${SCORE_THRESHOLD}).`,
      'Reminder: WhatsApp format only — *bold* with single asterisks, friendly GMT+8 times, no ## headers, no ISO timestamps.',
    ].join('\n'),
  },
}];

const prep = $('Code - parse keyword score').first().json;
const report = String($input.first().json.text ?? $input.first().json.response ?? '').trim();
if (!report) return [{ json: { skipped: true, reason: 'Report LLM returned empty text' } }];

function formatGmt8(value) {
  if (!value) return 'unknown time';
  const d = new Date(value);
  if (Number.isNaN(d.getTime())) return String(value);
  return d.toLocaleString('en-MY', {
    timeZone: 'Asia/Kuala_Lumpur',
    weekday: 'short',
    day: 'numeric',
    month: 'short',
    hour: 'numeric',
    minute: '2-digit',
    hour12: true,
  }) + ' (GMT+8)';
}

function toWhatsAppText(text) {
  return String(text)
    .replace(/\d{4}-\d{2}-\d{2}T[\d:.]+Z?/g, (m) => formatGmt8(m))
    .replace(/^#{1,6}\s*(.+)$/gm, '*$1*')
    .replace(/\*\*(.+?)\*\*/g, '*$1*')
    .replace(/^ActionNow Report:.+$/gim, '')
    .replace(/^Here's your summary.+$/gim, '')
    .replace(/^Here is your summary.+$/gim, '')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

const report_whatsapp = toWhatsAppText(report);
return [{ json: { ...prep, report_markdown: report, report_whatsapp } }];

